def plot_rank_changes(
    df:pd.DataFrame, # input DataFrame, 
    ignore:str|list='outs', # list of mapping types to exclude 'outs', ['outs', 'ccps']
    **kwargs # passed to plt.subplots (e.g. figsize, dpi)
    ):
    "Slope chart of rank changes (old → new) per mapping type, coloured by direction"
    if ignore is not None: df = df[~df.mapping_type.isin(L(ignore))]
    fig, axes = plt.subplots(1, df.mapping_type.nunique(), sharey=False, **kwargs)
    for ax, (mt, grp) in zip(axes, df.groupby('mapping_type')):
        for _, row in grp.iterrows():
            diff = 0 if pd.isna(row.rank_diff) else row.rank_diff
            color = 'steelblue' if diff < 0 else '#d9534f' if diff > 0 else 'grey'
            ax.plot([0, 1], [row.rank_old, row.rank_new], marker='o', color=color, alpha=1, lw=0.8)
            ax.text(0.5, (row.rank_old + row.rank_new) / 2 + (-0.15 * diff), row.theme_id,
                    ha='center', va='center', fontsize=8, fontweight='bold', color=color,
                    path_effects=[withStroke(linewidth=3, foreground='white')])
        ax.set_xticks([0, 1])
        ax.set_xticklabels(['Old', 'New'], fontsize=12)
        ax.invert_yaxis()
        ax.yaxis.set_major_locator(plt.MaxNLocator(integer=True))
        ax.set_title(mt, fontsize=12, fontweight='normal')
        ax.set_ylabel('Rank', fontsize=12)
    fig.suptitle("Rank Changes", fontsize=14, fontweight='normal')
    plt.tight_layout()
    plt.show()


