FUNDAMENTAL = 0.84

# %% ../../nbs/llm_eval/08_changes.ipynb #b3876f2b
def score_band(score):
    "Map a relevance score to its category label."
    if score >= FUNDAMENTAL: return 'FUNDAMENTAL'
    if score >= 0.66: return 'RELEVANT'
    if score >= 0.34: return 'PERIPHERAL'
    return 'NOT RELEVANT'

# %% ../../nbs/llm_eval/08_changes.ipynb #087b4ede
def is_fundamental(score): return score >= FUNDAMENTAL

# %% ../../nbs/llm_eval/08_changes.ipynb #5810457c
BANDS = ['NOT RELEVANT', 'PERIPHERAL', 'RELEVANT', 'FUNDAMENTAL']
BAND_LABELS = ['NOT REL.', 'PERI.', 'REL.', 'FUND.']
BAND_X = {b: i for i, b in enumerate(BANDS)}

# %% ../../nbs/llm_eval/08_changes.ipynb #aadfde70
def plot_band_changes(df, evl_id=None, ignore='outs', **kwargs):
    "Dot-arrow plot of score band changes (old → new) per theme, one subplot per mapping type"
    if evl_id is not None: df = df[df.evl_id == evl_id]
    if ignore is not None: df = df[~df.mapping_type.isin(L(ignore))]
    mts = sorted(df.mapping_type.unique())
    fig, axes = plt.subplots(1, len(mts), **kwargs)
    for ax, mt in zip(axes, mts):
        grp = df[df.mapping_type == mt].copy().sort_values('theme_id', key=lambda x: x.astype(int))
        grp['x_old'] = grp.score_old.map(score_band).map(BAND_X)
        grp['x_new'] = grp.score_new.map(score_band).map(BAND_X)
        for i, (_, row) in enumerate(grp.iterrows()):
            dx = row.x_new - row.x_old
            color = 'steelblue' if dx < 0 else '#d9534f' if dx > 0 else '#333'
            ax.annotate('', xy=(row.x_new, i), xytext=(row.x_old, i),
                        arrowprops=dict(arrowstyle='->' if dx != 0 else '-', color=color, lw=1))
            ax.scatter([row.x_old, row.x_new], [i, i], color=color, zorder=3, s=20)
        ax.set_yticks(range(len(grp)))
        ax.set_yticklabels(grp.theme_id.tolist(), fontsize=9)
        ax.set_xticks(range(len(BANDS)))
        ax.set_xticklabels(BAND_LABELS, fontsize=9)
        ax.set_xlim(-0.5, 3.5)
        ax.grid(axis='x', ls='--', alpha=0.4)
        ax.set_title(mt, fontsize=12, fontweight='normal')
    legend = [Line2D([0],[0], color='#d9534f', marker='o', lw=1, label='More Relevant'),
              Line2D([0],[0], color='steelblue', marker='o', lw=1, label='Less Relevant'),
              Line2D([0],[0], color='#333', marker='o', lw=1, label='Unchanged')]
    fig.legend(handles=legend, loc='lower center', ncol=3, fontsize=9, frameon=False, bbox_to_anchor=(0.5, -0.05))
    #fig.suptitle("Relevance Class Changes", fontsize=11, fontweight='normal')
    plt.tight_layout()
    plt.show()

