# %% ../../nbs/llm_eval/08_changes.ipynb #f470024b
def plot_theme_stats(
    ts, # theme stats dataframe
    mapping_type, # mapping type to plot
    alpha=0.05, # alpha threshold for significance
    show_pval=False, # whether to show p-values
    **kwargs
    ):
    "Forest plot of bootstrap CIs per theme for a given mapping type, annotated with p-value"
    d = ts[ts.mapping_type==mapping_type].copy()
    d['theme_id'] = d['theme_id'].astype(int)
    d = d.sort_values('theme_id')
    f, ax = plt.subplots(**kwargs)
    for _, row in d.iterrows():
        color = '#d9534f' if row.pvalue < alpha else 'grey'
        ax.errorbar(row.theme_id, row['mean'], yerr=[[row['mean']-row.ci_low], [row.ci_high-row['mean']]], fmt='o', color=color, ecolor=color, elinewidth=1, capsize=3, ms=5)
        pstr = "p<0.001" if row.pvalue < 0.001 else f"p={row.pvalue:.3f}"
        if show_pval: ax.text(row.theme_id, d.ci_high.max() + 0.01, pstr, ha='center', fontsize=7, color=color)
    ax.axhline(0, color='black', linewidth=0.8, linestyle='--')
    ax.set_xticks(d.theme_id)
    ax.set(xlabel=mapping_type, ylabel='mean score diff (bootstrap)',)
    sns.despine(left=True, bottom=True)
    plt.tight_layout()

# %% ../../nbs/llm_eval/08_changes.ipynb #90232538
def get_theme(
    result:dict, # loaded .json tagging result
    mapping_type, # 'gcms', 'enbs', 'ccps', 'outs'
    theme_id:str # theme ID
    ):
    "Get a single theme dict from a result by mapping_type and theme_id"
    return next((t for t in result['mappings'][mapping_type] if str(t['theme_id']) == str(theme_id)), None)

# %% ../../nbs/llm_eval/08_changes.ipynb #b41a28b5
def theme_md(
    mapping_type:str, # 'gcms', 'enbs', 'ccps', 'outs' 
    theme_id:str, # theme ID 
    old_r:dict, # old taggingresult 
    new_r:dict, # new tagging result
    row:pd.Series # row from df of delta between old and new
    ):
    "Render a single theme comparison as markdown with collapsible reasoning"
    o,n = get_theme(old_r, mapping_type, theme_id), get_theme(new_r, mapping_type, theme_id)
    return f"""#### {mapping_type.upper()} {n['theme_id']}: {n['theme_title']}

| score_old | score_new | rank_old | rank_new | rank_diff |
|---|---|---|---|---|
| {row.score_old} | {row.score_new} | {row.rank_old} | {row.rank_new} | {row.rank_diff} |

<details><summary>Reasoning (old)</summary>{o['reasoning']}</details>

---

<details><summary>Reasoning (new)</summary>{n['reasoning']}</details>"""

# %% ../../nbs/llm_eval/08_changes.ipynb #bb27f6cc
def fundamental_transitions(
    df:pd.DataFrame,  # deltas DataFrame for a single report
    exclude_types     # mapping types to exclude
):
    "Rows where fundamental status changed between old and new score."
    d = df[~df.mapping_type.isin(exclude_types)].copy()
    d['was'] = d.score_old.map(is_fundamental)
    d['now'] = d.score_new.map(is_fundamental)
    return d[d.was & ~d.now], d[~d.was & d.now]

# %% ../../nbs/llm_eval/08_changes.ipynb #74588430
async def add_theme_cells(mid, label, rows, old_r, new_r):
    "Post label header + one cell per theme row to the dialog."
    mid = await add_msg(f"**{label}**", placement='add_after', id=mid)
    for mt,tid,row in rows: mid = await add_msg(theme_md(mt, tid, old_r, new_r, row), placement='add_after', id=mid)
    return mid

# %% ../../nbs/llm_eval/08_changes.ipynb #42947dc8
def fundamental_themes(df, score_col, exclude_types):
    "List fundamental themes for a given score column."
    d = df[~df.mapping_type.isin(exclude_types) & df[score_col].map(is_fundamental)]
    return [(row.mapping_type, str(row.theme_id), row.theme_title_x if 'theme_title_x' in d.columns else row.theme_title) for _,row in d.iterrows()]

# %% ../../nbs/llm_eval/08_changes.ipynb #41c4f03d
async def add_fundamental_summary(mid, df, exclude_types, old_r, new_r):
    "Post a summary table of fundamental themes (old vs new) to the dialog."
    rows_old = fundamental_themes(df, 'score_old', exclude_types)
    rows_new = fundamental_themes(df, 'score_new', exclude_types)
    lines = ['**Fundamental Themes**', '| | Mapping | Theme | Score |', '|---|---|---|---|']
    for mt,tid,title in rows_old: lines.append(f'| old | {mt} | {tid}: {title} | {df[(df.mapping_type==mt)&(df.theme_id.astype(str)==tid)].score_old.values[0]:.2f} |')
    for mt,tid,title in rows_new: lines.append(f'| new | {mt} | {tid}: {title} | {df[(df.mapping_type==mt)&(df.theme_id.astype(str)==tid)].score_new.values[0]:.2f} |')
    return await add_msg('\n'.join(lines), placement='add_after', id=mid)

# %% ../../nbs/llm_eval/08_changes.ipynb #f82f3e11
async def gen_report_cells(
    rpt_id,                   # report ID
    dfs,                      # combined deltas DataFrame from all_deltas
    old_results_path,         # path to old/backup results
    new_results_path,         # path to new results
    exclude_types=('outs',),  # mapping types to exclude
    plot_kwargs=None          # kwargs passed to plot_rank_changes
):
    "Generate dialog cells comparing old vs new mappings for a report."
    old_r,new_r = load_result(rpt_id, old_results_path), load_result(rpt_id, new_results_path)
    mid = await add_msg(f"### {new_r['meta']['Title']}", placement='at_end')
    pkw = ifnone(plot_kwargs, dict(figsize=(10,5), dpi=77))
    plot_code = f"plot_band_changes(dfs[dfs.evl_id == '{rpt_id}'], {', '.join(f'{k}={v}' for k,v in pkw.items())})"
    mid = await add_msg(plot_code, msg_type='code', run=False, placement='add_after', id=mid)
    mid = await add_fundamental_summary(mid, dfs[dfs.evl_id == rpt_id], exclude_types, old_r, new_r)
    lost,gained = fundamental_transitions(dfs[dfs.evl_id == rpt_id], exclude_types)
    for df,label in [(lost,'⬇️ No Longer Fundamental'),(gained,'⬆️ Now Fundamental')]:
        rows = [(row.mapping_type,str(row.theme_id),row) for _,row in df.iterrows()]
        if rows: mid = await add_theme_cells(mid, label, rows, old_r, new_r)
    return mid
